#[derive(Clone, Debug, PartialEq, Hash, Eq)]
pub enum TablePartition {
    MvdbPartition(MvdbPartition),
    WorklogPartition(WorklogPartition),
}

impl Default for TablePartition {
    fn default() -> Self {
        Self::MvdbPartition(MvdbPartition::default())
    }
}

impl TablePartition {
    pub fn serialize_to(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder,
    ) -> (WIPOffset<UnionWIPOffset>, FbsTablePartition) {
        match self {
            Self::MvdbPartition(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsTablePartition::MvdbPartition;
                (offset, ty)
            }
            Self::WorklogPartition(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsTablePartition::WorklogPartition;
                (offset, ty)
            }
        }
    }
}

#[derive(Default, PartialEq, Debug, Clone, Hash, Eq)]
pub struct DataCatalog {
    pub id: ObjectId,
    /// The partition of the table to query; can be null.
    pub partition: Option<TablePartition>,
    pub revision: Option<ContentId>,
}

impl DataCatalog {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsDataCatalog<'a>> {
        use crate::types::generated::query_generated::DataCatalogBuilder as FbsDataCatalogBuilder;

        let id_offset = self.id.serialize_to(builder);
        let partition_offset = self.partition.as_ref().map(|u| u.serialize_to(builder));
        let revision_offset = self.revision.as_ref().map(|o| o.serialize_to(builder));

        let mut bldr = FbsDataCatalogBuilder::new(builder);
        bldr.add_id(id_offset);
        if let Some((offset, ty)) = partition_offset {
            bldr.add_partition(offset);
            bldr.add_partition_type(ty);
        }
        if let Some(offset) = revision_offset {
            bldr.add_revision(offset);
        }
        bldr.finish()
    }
}

impl From<FbsDataCatalog<'_>> for DataCatalog {
    fn from(fbs: FbsDataCatalog<'_>) -> Self {
        let id = ObjectId::from(fbs.id());
        let partition = if let Some(val) = fbs.partition() {
            let partition = match fbs.partition_type() {
                FbsTablePartition::MvdbPartition => TablePartition::MvdbPartition(
                    MvdbPartition::from(fbs.partition_as_mvdb_partition().unwrap()),
                ),
                FbsTablePartition::WorklogPartition => TablePartition::WorklogPartition(
                    WorklogPartition::from(fbs.partition_as_worklog_partition().unwrap()),
                ),
                _ => unreachable!(),
            };

            Some(partition)
        } else {
            None
        };

        let revision = fbs.revision().map(ContentId::from);
        Self {
            id,
            partition,
            revision,
        }
    }
}

